"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type SwitchProps = Omit<React.ComponentProps<"input">, "type" | "role" | "children" | "onChange"> & {
  /** The sentence, up to its last word: "Email me when someone replies:". */
  children: React.ReactNode
  onCheckedChange?: (checked: boolean) => void
  /** The word for on, in italic. */
  on?: string
  /** The word for off. */
  off?: string
  /** Classes for the label, which is the root. className goes to the input. */
  labelClassName?: string
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

/**
 * A sentence whose last word you can change. The state word rolls between on and
 * off in italic, and the full stop answers: a dot when on, a ring when off.
 * A native checkbox with the switch role, so Space toggles it.
 */
function Switch({ children, onCheckedChange, on = "on", off = "off", className, labelClassName, "data-force": force, ...props }: SwitchProps) {
  return (
    <label data-slot="switch" data-force={force} className={cn("db-switch", labelClassName)}>
      <input type="checkbox" role="switch" className={className} onChange={(e) => onCheckedChange?.(e.target.checked)} {...props} />
      {children}{" "}
      <span className="db-switch-state" aria-hidden="true">
        <span>{on}</span>
        <span>{off}</span>
      </span>
      <span className="db-switch-stop" aria-hidden="true" />
    </label>
  )
}

export { Switch, type SwitchProps }

@layer components {
  /* ── db-switch ── a sentence whose last word you can change */
  .db-switch { position: relative; display: inline-block; cursor: pointer; color: var(--db-graphite); -webkit-tap-highlight-color: transparent; }
  .db-switch > input { position: absolute; width: 1px; height: 1px; margin: 0; opacity: 0; pointer-events: none; }
  .db-switch-state {
    display: inline-grid; vertical-align: baseline; overflow: clip;
    padding: 0.12em 0.14em 0.24em; margin-block: -0.12em -0.24em; margin-inline: -0.08em -0.14em;
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1;
    color: var(--db-ink);
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0.14em calc(100% - 0.1em) / calc(100% - 0.28em) var(--db-hairline);
    transition: color var(--db-moderato) var(--db-breath);
  }
  .db-switch-state > span { grid-area: 1 / 1; transition: translate var(--db-moderato) var(--db-breath), opacity var(--db-moderato) var(--db-breath); }
  .db-switch > input:not(:checked) ~ .db-switch-state { color: var(--db-pencil); }
  .db-switch > input:not(:checked) ~ .db-switch-state > :first-child { translate: 0 -110%; opacity: 0; }
  .db-switch > input:checked ~ .db-switch-state > :last-child { translate: 0 110%; opacity: 0; }
  .db-switch:is(:hover, [data-force~="hover"]) > .db-switch-state { background-image: linear-gradient(var(--db-ink), var(--db-ink)); }
  .db-switch > input:focus-visible ~ .db-switch-state,
  .db-switch[data-force~="focus"] > .db-switch-state { outline: var(--db-stroke) solid var(--db-accent); outline-offset: 0; }
  .db-switch[data-force~="focus"] { outline: 0; }
  .db-switch:has(input:disabled) { opacity: 0.55; cursor: not-allowed; }
  /* The sentence's full stop: a dot when on, a ring when off. */
  .db-switch-stop {
    display: inline-block; width: max(0.22em, 5px); height: max(0.22em, 5px); margin-inline-start: 0.24em; border-radius: 50%;
    box-shadow: inset 0 0 0 0.5em currentColor;
    transition: box-shadow var(--db-andante) var(--db-exhale);
  }
  .db-switch > input:not(:checked) ~ .db-switch-stop { box-shadow: inset 0 0 0 var(--db-hairline) currentColor; }
}
